import {client as sharedClient, access as sharedAccess, accessGate} from './auth.js';
'use strict';
/** HÆMA — Portal privado. No private content is fetched before Supabase Auth.
 * The browser receives a publishable key only; PostgreSQL RLS is authoritative.
 * No lore or new game mechanics are inferred or generated by this interface.
 */
const PORTAL=(()=>{
 const $=(q,root=document)=>root.querySelector(q);
 const $all=(q,root=document)=>[...root.querySelectorAll(q)];
 const node=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=String(text);return el};
 const add=(parent,...children)=>{parent.append(...children);return parent};
 const b=(label,action,cls='portal-ghost')=>{const btn=node('button',cls,label);btn.type='button';btn.addEventListener('click',action);return btn};
 const brief=(text)=>node('p','portal-info',text);
 const empty=(text)=>node('div','portal-empty',text);
 const formatTime=s=>{if(!s)return '';const d=new Date(s);return Number.isFinite(d.getTime())?d.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):''};
 const safe=(value,max=20000)=>String(value??'').slice(0,max);
 const fresh=()=>({format:'haema-character',version:'0.1',name:'',job:'',attributes:Array(6).fill(4),skills:Array(24).fill(4),wounds:0,integrity:null,stamina:null,impetus:0,overload:0,metus:0});
 const isValidSheet=c=>!!c&&c.format==='haema-character'&&c.version==='0.1'&&Array.isArray(c.attributes)&&c.attributes.length===6&&c.attributes.every(x=>[4,6,8].includes(x))&&Array.isArray(c.skills)&&c.skills.length===24&&c.skills.every(x=>[4,6,8].includes(x))&&c.attributes.reduce((s,x)=>s+(x-4)/2,0)<=6&&c.skills.reduce((s,x)=>s+(x-4)/2,0)<=8;
 const state={client:null,user:null,admin:false,campaigns:[],current:null,tab:'home',data:{},live:null,authBound:false,boot:null,epoch:0};
 const currentRoot=()=>document.getElementById('haema-portal-app');
 const errorText=e=>safe(e?.message||'Não foi possível concluir esta operação.',350);
 const message=(root,text,isError=false)=>{let target=$('.portal-feedback',root);if(!target){target=node('div','portal-feedback');root.prepend(target)}target.className='portal-feedback '+(isError?'portal-err':'portal-success');target.textContent=text;};
 const field=(label,type='text',value='',maxLength)=>{
  const wrap=node('div','portal-field');const lab=node('label','',label);const el=type==='textarea'?node('textarea'):node('input');
  if(type!=='textarea')el.type=type;el.value=value??'';if(maxLength)el.maxLength=maxLength;
  wrap.append(lab,el);return {wrap,input:el};
 };
 const selectField=(label,options,value)=>{
  const wrap=node('div','portal-field');wrap.append(node('label','',label));const select=node('select');
  for(const [code,title] of options){const o=node('option','',title);o.value=code;select.append(o)}
  select.value=value??options[0]?.[0];wrap.append(select);return{wrap,input:select};
 };
 const title=(label,description,action)=>{
  const h=node('div','portal-section-head'),left=node('div');left.append(node('p','portal-overline','HAEMATOMANTHÍA · PORTAL 0.1'),node('h2','',label));
  if(description)left.append(node('p','',description));h.append(left);if(action)h.append(action);return h;
 };
 const notify=async(promise,root,success)=>{try{const r=await promise;if(r?.error)throw r.error;if(success)message(root,success);return r}catch(e){message(root,errorText(e),true);return null}};
 const query=async(q)=>{const r=await q;if(r.error)throw r.error;return r.data};
 const ensureClient=async()=>{state.client=await sharedClient();return state.client;};
 function setup(root){
  root.replaceChildren();const card=node('div','portal-setup');card.append(node('p','portal-overline','PORTAL EM PREPARAÇÃO'),node('h2','','Um espaço reservado à sua campanha.'),node('p','','O login Google ainda não está configurado neste ambiente. O Portal não concede permissões sem autenticação real nem expõe registros privados.'));
  card.append(brief('A configuração exige Supabase Auth (Google), as políticas de acesso por campanha e as variáveis públicas da Vercel. O site atual continua funcionando normalmente.'));
  const foot=node('div','portal-access-points');for(const [name,desc] of [['JOGADORES','Personagens, fichas, materiais e conversa da campanha.'],['MESTRE','Acompanhamento de personagens, registros, lore, sistema e trilha de auditoria.']]){const c=node('div');c.append(node('strong','',name),node('span','',desc));foot.append(c)}card.append(foot);
  const button=b('Entrar com Google',()=>{},'portal-action');button.disabled=true;button.title='Disponível quando a autenticação Google for configurada';card.append(button,node('p','portal-note','A ativação depende do Supabase Auth, do Google OAuth e do cadastro inicial do mestre.'));
  root.append(card);
 }
 function signin(root){
  root.replaceChildren();const card=node('div','portal-auth');card.append(node('p','portal-overline','ACESSO DA CAMPANHA'),node('h2','','Entre no seu lugar à mesa.'),node('p','','Use sua conta Google para acessar os personagens, materiais e conversas compartilhados com você. A área do mestre só é liberada pela campanha.'));
  const features=node('div','portal-access-points');
  for(const [name,desc] of [['PERSONAGENS','Fichas 0.1 salvas online, com versões preservadas.'],['ACERVO & CONVERSA','O que o mestre liberou e o chat da sua mesa.']]){const c=node('div');c.append(node('strong','',name),node('span','',desc));features.append(c)}
  card.append(features);
  const btn=b('Entrar com Google',async()=>{
   btn.disabled=true;const{error}=await state.client.auth.signInWithOAuth({provider:'google',options:{redirectTo:new URL('portal.html',location.origin+'/').href}});
   if(error){btn.disabled=false;message(card,errorText(error),true)}
  },'portal-action');
  card.append(btn,node('p','portal-note','O Google autentica sua conta; o mestre vê seus personagens e atividades na campanha, não sua senha nem informações privadas da conta Google.'));
  root.append(card);
 }
 async function profile(){
  const u=state.user;let display=safe(u.user_metadata?.full_name||u.user_metadata?.name||'Jogador',80).trim()||'Jogador';
  const avatar=safe(u.user_metadata?.avatar_url||'',500);
  await query(state.client.from('haema_profiles').upsert({id:u.id,display_name:display,avatar_url:avatar,updated_at:new Date().toISOString()},{onConflict:'id'}));
 }
 async function fetchCampaigns(){
  const rows=await query(state.client.from('haema_members').select('campaign_id,role').eq('user_id',state.user.id));
  if(!rows.length){state.campaigns=[];state.current=null;return;}
  const campaigns=await query(state.client.from('haema_campaigns').select('id,name,description,gm_id').in('id',rows.map(r=>r.campaign_id)));
  state.campaigns=campaigns.map(c=>({...c,role:rows.find(r=>r.campaign_id===c.id)?.role||'player'}));
  state.current=state.campaigns.find(c=>c.id===state.current?.id)||state.campaigns[0]||null;
 }
 function noCampaign(root){
  root.replaceChildren();const card=node('div','portal-setup');
  card.append(node('h2','','Aguardando sua campanha.'),node('p','','O administrador pode associar sua conta a uma campanha pelo painel de acessos.'));
  if(state.admin){const gm=node('form','portal-form');gm.append(node('h3','','Criar campanha como mestre'));
   const name=field('Nome da campanha','text','',100),desc=field('Descrição inicial','textarea','',1200);name.input.required=true;gm.append(name.wrap,desc.wrap);
   const submit=b('Criar campanha',()=>{},'portal-action');submit.type='submit';gm.append(submit);
   gm.addEventListener('submit',async e=>{e.preventDefault();submit.disabled=true;const r=await notify(state.client.from('haema_campaigns').insert({gm_id:state.user.id,name:name.input.value.trim(),description:desc.input.value.trim()}),gm,'Campanha criada.');submit.disabled=false;if(r)await reload(root)});
   card.append(gm);
  }
  card.append(b('Sair da conta',async()=>{await state.client.auth.signOut();state.user=null;signin(root)}));
  root.append(card);
 }
 document.addEventListener('haema:auth',()=>void init());
 const isGM=()=>state.current?.gm_id===state.user?.id;
 const campaignId=()=>state.current.id;
 function sidebar(root){
  const aside=node('aside','portal-sidebar');const user=node('div','portal-user');const avatar=node('div','portal-avatar');
  const initial=safe(state.user.user_metadata?.full_name||'H',1);avatar.textContent=initial.toUpperCase();
  const display=node('div');display.append(node('strong','',safe(state.user.user_metadata?.full_name||'Jogador',80)),node('small','',isGM()?'MESTRE DA CAMPANHA':'JOGADOR'));
  user.append(avatar,display);aside.append(user);
  if(state.campaigns.length>1){const choose=node('div','portal-selector');choose.append(node('label','','CAMPANHA'));
   const select=node('select');for(const c of state.campaigns){const o=node('option','',c.name);o.value=c.id;select.append(o)}select.value=campaignId();select.addEventListener('change',()=>{state.current=state.campaigns.find(c=>c.id===select.value);state.tab='home';void renderDashboard(root)});choose.append(select);aside.append(choose)}
  const tabs=node('nav','portal-tabs');tabs.setAttribute('aria-label','Áreas do portal');
  const options=[['home','✧','Visão geral'],['characters','♧','Personagens'],['chat','◈','Conversa']];if(state.materials)options.push(['materials','✦','Materiais']);if(isGM())options.push(['gm','♜','Painel do Mestre']);
  for(const[id,mark,label]of options){const tab=node('button','portal-tab'+(id===state.tab?' is-active':''));tab.type='button';tab.setAttribute('aria-current',id===state.tab?'page':'false');tab.append(node('span','portal-tab-mark',mark),node('span','',label));tab.addEventListener('click',()=>{state.tab=id;void renderDashboard(root)});tabs.append(tab)}
  aside.append(tabs);const end=node('div','portal-sidebar-end');end.append(b('Sair',async()=>{await state.client.auth.signOut();state.user=null;state.current=null;signin(root)}));aside.append(end);return aside;
 }
 async function loadCampaignData(){
  const id=campaignId(),s=state.client,gm=isGM();
  const qs=[
   s.from('haema_characters').select('id,campaign_id,user_id,title,rules_version,payload,updated_at').eq('campaign_id',id).order('updated_at',{ascending:false}),
   state.materials?s.from('haema_materials').select('id,title,kind,content,visibility,updated_at').eq('campaign_id',id).order('updated_at',{ascending:false}):Promise.resolve({data:[]}),
   s.from('haema_messages').select('id,author_id,content,created_at').eq('campaign_id',id).order('created_at',{ascending:false}).limit(100),
   state.materials?s.from('haema_gm_records').select('id,category,title,content,status,visibility,updated_at').eq('campaign_id',id).order('updated_at',{ascending:false}):Promise.resolve({data:[]}),
   gm?s.from('haema_members').select('user_id,role,joined_at').eq('campaign_id',id):Promise.resolve({data:[]}),
   gm?s.from('haema_audit').select('id,actor_id,entity_type,entity_id,action,occurred_at').eq('campaign_id',id).order('occurred_at',{ascending:false}).limit(60):Promise.resolve({data:[]}),
   s.from('haema_mesa_grants').select('user_id,granted_at').order('granted_at',{ascending:false})
  ];
  const result=await Promise.all(qs.map(query));
  const [characters,materials,messages,records,members,audit,mesaGrants]=result;
  const ids=[...new Set([...members.map(m=>m.user_id),...messages.map(m=>m.author_id),...characters.map(c=>c.user_id)])];
  let profiles=[];if(ids.length)profiles=await query(s.from('haema_profiles').select('id,display_name').in('id',ids));
  const names=Object.fromEntries(profiles.map(p=>[p.id,p.display_name]));
  return{characters,materials,messages:messages.reverse(),records,members,audit,names,mesaGrants};
 }
 async function subscribeChat(){
  if(state.live){await state.client.removeChannel(state.live);state.live=null;}
  const id=campaignId();state.live=state.client.channel('haema-chat-'+id)
   .on('postgres_changes',{event:'INSERT',schema:'public',table:'haema_messages',filter:'campaign_id=eq.'+id},()=>{if(state.current?.id===id&&state.tab==='chat'&&currentRoot())void renderDashboard(currentRoot())})
   .subscribe();
 }
 async function renderDashboard(root){
  if(!root||!state.current)return;
  const epoch=++state.epoch;root.replaceChildren(node('div','portal-loading','Carregando os registros da campanha...'));
  try{const all=await loadCampaignData();if(epoch!==state.epoch||root!==currentRoot())return;
   state.data=all;root.replaceChildren();const grid=node('div','portal-grid'),aside=sidebar(root),panel=node('section','portal-panel');
   grid.append(aside,panel);root.append(grid);
   if(state.tab==='characters')showCharacters(panel,root);
   else if(state.tab==='materials')showMaterials(panel,root);
   else if(state.tab==='chat')showChat(panel,root);
   else if(state.tab==='gm'&&isGM())showGM(panel,root);
   else showHome(panel,root);
   // Subscribe once per campaign; suppress duplicate subscriptions across view updates.
   if(!state.live||state.live.topic!=='realtime:haema-chat-'+campaignId())void subscribeChat();
  }catch(e){if(epoch!==state.epoch)return;root.replaceChildren();const box=node('div','portal-setup');box.append(node('h2','','Não foi possível carregar a campanha.'),node('p','',errorText(e)),b('Tentar novamente',()=>void renderDashboard(root),'portal-action'));root.append(box)}
 }
 function showHome(panel,root){
  panel.append(title(state.current.name,state.current.description||'Sua campanha, sua história.'));
  const cards=node('div','portal-cards');for(const [value,label,caption] of [
   [state.data.characters.length,'Personagens','Fichas HÆMA 0.1'],[state.data.materials.filter(x=>x.visibility==='players').length,'Materiais','Liberados à mesa'],[state.data.messages.length,'Mensagens','Últimas 100 no chat']]){
   const c=node('div','portal-card');c.append(node('strong','',value),node('span','',label),node('p','',caption));cards.append(c)}panel.append(cards);
  panel.append(node('hr','portal-divider-line'));
  panel.append(node('p','portal-overline',isGM()?'ESCUDO DO MESTRE':'SEU ESPAÇO NA MESA'));
  panel.append(brief(isGM()?'Acompanhe as fichas dos jogadores, publique materiais e mantenha seu arquivo de lore e sistema com histórico de alterações.':'Seu personagem e o que foi compartilhado com ele ficam juntos. Acesse o acervo ou entre na conversa da campanha.'));
  const actions=node('div','portal-flex');actions.append(b('Ver personagens',()=>{state.tab='characters';void renderDashboard(root)},'portal-action'));if(state.materials)actions.append(b('Abrir acervo',()=>{state.tab='materials';void renderDashboard(root)}));if(isGM())actions.append(b('Painel do Mestre',()=>{state.tab='gm';void renderDashboard(root)}));if(state.data.mesaGrants.some(g=>g.user_id===state.user.id)||state.admin)actions.append(b('Abrir Mesa de Jogo',()=>{location.href='mesa.html'},'portal-action'));panel.append(actions);
 }
 function characterCard(character,panel,root){
  const card=node('article','portal-item'),top=node('div','portal-item-top'),head=node('div');head.append(node('h3','',character.title),node('span','portal-meta',(state.data.names[character.user_id]||'Jogador')+' · HÆMA '+character.rules_version));
  top.append(head,node('span','portal-tag','FICHA 0.1'));card.append(top);
  const controls=node('div','portal-flex');const mine=character.user_id===state.user.id;
  controls.append(b(mine?'Editar ficha':'Consultar ficha',()=>editCharacter(panel,root,character,!mine)));
  card.append(controls);return card;
 }
 function showCharacters(panel,root){
  const actions=node('div','portal-flex');actions.append(b('Criar personagem',()=>editCharacter(panel,root,null,false),'portal-action'));
  let hasLocal=false;try{hasLocal=!!localStorage.getItem('haema-character-0.1')}catch{}
  if(hasLocal)actions.append(b('Importar ficha deste dispositivo',()=>void importLocal(panel,root)));
  panel.append(title('Personagens',isGM()?'Veja as fichas dos integrantes da campanha. Cada jogador edita a própria ficha.':'Crie personagens e mantenha a ficha atualizada. Sua ficha local antiga nunca é apagada.',actions));
  const list=node('div','portal-list');if(!state.data.characters.length)list.append(empty('Ainda não existem fichas nesta campanha. Crie a primeira quando quiser.'));
  else for(const character of state.data.characters)list.append(characterCard(character,panel,root));panel.append(list);
 }
 async function importLocal(panel,root){
  try{const raw=localStorage.getItem('haema-character-0.1');if(!raw)throw Error('Nenhuma ficha local encontrada.');const payload=JSON.parse(raw);if(!isValidSheet(payload))throw Error('Ficha local inválida ou de outra versão. Não foi alterada.');
   const r=await notify(state.client.from('haema_characters').insert({campaign_id:campaignId(),user_id:state.user.id,title:payload.name?.trim()||'Personagem sem nome',rules_version:'0.1',payload}),panel,'Uma cópia da ficha local foi salva online. A original continua neste dispositivo.');
   if(r)await renderDashboard(root);
  }catch(e){message(panel,errorText(e),true)}
 }
 function editCharacter(panel,root,existing,readOnly){
  panel.replaceChildren();const p=existing?structuredClone(existing.payload):fresh();
  panel.append(title(readOnly?'Ficha do personagem':existing?'Editar personagem':'Criar personagem','Dados do Núcleo Jogável 0.1. Não há classes obrigatórias nem regras sobrenaturais inventadas.',b('Voltar',()=>void renderDashboard(root))));
  const form=node('form','portal-form');const name=field('Nome do personagem','text',p.name||'',80),job=field('Profissão','text',p.job||'',100);name.input.required=true;form.append(name.wrap,job.wrap);
  const core=window.HAEMA01;if(!core){form.append(empty('O núcleo HÆMA 0.1 não está carregado.'));panel.append(form);return}
  const createGroup=(label,names,arr,budget)=>{
   const group=node('section');group.append(node('h3','',label));const counter=node('p','portal-info');group.append(counter);const grid=node('div','portal-sheet-grid');
   function updateBudget(){const used=core.steps(arr);counter.textContent=`${used} de ${budget} avanços usados · máximo d8 na criação`;counter.style.color=used>budget?'#f4a6a6':''}
   for(let i=0;i<names.length;i++){
    const wrap=node('div','portal-dice-field'),lab=node('span','',names[i]),sel=node('select');sel.setAttribute('aria-label',names[i]);
    for(const size of [4,6,8]){const o=node('option','','d'+size);o.value=size;sel.append(o)}sel.value=String(arr[i]);
    sel.addEventListener('change',()=>{const before=arr[i];arr[i]=Number(sel.value);if(core.steps(arr)>budget){arr[i]=before;sel.value=String(before);message(form,'Limite de avanços excedido. A escolha foi desfeita.',true)}updateBudget()});
    if(readOnly)sel.disabled=true;wrap.append(lab,sel);grid.append(wrap);
   }group.append(grid);updateBudget();return group;
  };
  form.append(createGroup('Atributos',core.ATTR,p.attributes,6),createGroup('Competências',core.SKILLS,p.skills,8));
  const extra=node('div','portal-form-row'),meta=[['Ferimentos','wounds',0,2],['Ímpeto','impetus',0,3],['Sobrecarga','overload',0,6],['Metus','metus',0,8],['Integridade atual','integrity',0,30],['Fôlego atual','stamina',0,20]];
  for(const[label,key,min,max]of meta){const f=field(label,'number',p[key]??'',5);f.input.min=min;f.input.max=max;f.input.step=key==='metus'?2:1;f.input.placeholder='Automático';
   if(key==='metus')f.input.placeholder='0, 4, 6 ou 8';if(readOnly)f.input.disabled=true;
   f.input.addEventListener('change',()=>{const val=f.input.value.trim();p[key]=val===''?null:Number(val)});extra.append(f.wrap)}form.append(node('h3','','Condições atuais'),extra);
  if(readOnly){name.input.disabled=true;job.input.disabled=true;form.append(brief('Consulta do mestre: a edição pertence ao jogador dono desta ficha.'))}
  else {const footer=node('div','portal-form-foot');footer.append(b('Cancelar',()=>void renderDashboard(root)));
   const save=b('Salvar ficha online',()=>{},'portal-action');save.type='submit';footer.append(save);form.append(footer);
   form.addEventListener('submit',async e=>{e.preventDefault();p.name=name.input.value.trim();p.job=job.input.value.trim();if(!p.name||!isValidSheet(p)){message(form,'Revise o nome e os avanços. A ficha não foi salva.',true);return}
    if(![null,0,4,6,8].includes(p.metus)){message(form,'Metus deve ser 0, d4, d6 ou d8.',true);return}
    const maximum=core.resources(p.attributes[2],p.wounds);
    if(p.integrity!=null&&(p.integrity<0||p.integrity>maximum.integrity)||p.stamina!=null&&(p.stamina<0||p.stamina>maximum.stamina)){message(form,'Integridade ou Fôlego além do limite desta ficha.',true);return}
    save.disabled=true;const payload={title:p.name,payload:p,updated_at:new Date().toISOString()};
    const op=existing?state.client.from('haema_characters').update(payload).eq('id',existing.id):state.client.from('haema_characters').insert({...payload,campaign_id:campaignId(),user_id:state.user.id,rules_version:'0.1'});
    const res=await notify(op,form,'Ficha salva online.');save.disabled=false;if(res)await renderDashboard(root);
   });
  }
  panel.append(form);
 }
 function showMaterials(panel,root){
  const gm=isGM();panel.append(title('Acervo da campanha','Documentos, pistas e referências. O mestre escolhe o que os jogadores podem ver.',gm?b('Novo material',()=>materialForm(panel,root),'portal-action'):null));
  const list=node('div','portal-list');if(!state.data.materials.length)list.append(empty('Nenhum material disponível para esta campanha.'));
  for(const m of state.data.materials){const card=node('article','portal-item'),head=node('div','portal-item-top');head.append(node('h3','',m.title),node('span','portal-tag',(m.visibility==='gm'?'PRIVADO · MESTRE':'COMPARTILHADO')+' · '+m.kind));card.append(head,node('p','',m.content||'Sem descrição'),node('p','portal-meta','Atualizado em '+formatTime(m.updated_at)));if(gm)card.append(b('Editar',()=>materialForm(panel,root,m)));list.append(card)}panel.append(list);
 }
 function materialForm(panel,root,existing){if(!isGM())return;panel.replaceChildren(title(existing?'Editar material':'Novo material','Só materiais marcados como compartilhados ficam visíveis aos jogadores.',b('Voltar',()=>void renderDashboard(root))));
  const form=node('form','portal-form'),titleField=field('Título','text',existing?.title||'',120),kind=selectField('Tipo',[['documento','Documento'],['pista','Pista'],['referencia','Referência'],['mapa','Mapa / descrição']],existing?.kind),visibility=selectField('Acesso',[['players','Compartilhado com jogadores'],['gm','Somente mestre']],existing?.visibility),body=field('Conteúdo do material','textarea',existing?.content||'',20000);
  titleField.input.required=true;form.append(titleField.wrap,kind.wrap,visibility.wrap,body.wrap);const save=b('Salvar material',()=>{},'portal-action');save.type='submit';form.append(save);form.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;
   const value={title:titleField.input.value.trim(),kind:kind.input.value,visibility:visibility.input.value,content:body.input.value,updated_at:new Date().toISOString()};
   const op=existing?state.client.from('haema_materials').update(value).eq('id',existing.id):state.client.from('haema_materials').insert({...value,campaign_id:campaignId(),author_id:state.user.id});
   const result=await notify(op,form,'Material salvo.');save.disabled=false;if(result)await renderDashboard(root);
  });panel.append(form);
 }
 function showChat(panel,root){
  panel.append(title('Conversa da mesa','Chat compartilhado da campanha. Todos os integrantes e o mestre podem ler as mensagens.'));
  const area=node('div','portal-chat');area.setAttribute('role','log');area.setAttribute('aria-label','Mensagens recentes');
  if(!state.data.messages.length)area.append(empty('A conversa ainda está vazia. Que tal começar?'));
  for(const m of state.data.messages){const mine=m.author_id===state.user.id;const msg=node('article','portal-message'+(mine?' mine':''));const head=node('header');head.append(node('strong','',state.data.names[m.author_id]||'Integrante'),node('span','',formatTime(m.created_at)));msg.append(head,node('p','',m.content));area.append(msg)}panel.append(area);
  const form=node('form','portal-chat-form'),input=node('input');input.type='text';input.placeholder='Escreva uma mensagem para a mesa...';input.maxLength=1500;input.required=true;input.setAttribute('aria-label','Mensagem');
  const send=b('Enviar',()=>{},'portal-action');send.type='submit';form.append(input,send);form.addEventListener('submit',async e=>{e.preventDefault();const value=input.value.trim();if(!value)return;send.disabled=true;
   const r=await notify(state.client.from('haema_messages').insert({campaign_id:campaignId(),author_id:state.user.id,content:value}),form);send.disabled=false;if(r){input.value='';await renderDashboard(root)}});
  panel.append(form);requestAnimationFrame(()=>{area.scrollTop=area.scrollHeight});
 }
 function gmItem(record,panel,root){const card=node('article','portal-item'),top=node('div','portal-item-top');top.append(node('h3','',record.title),node('span','portal-tag',record.status.toUpperCase()));card.append(top,node('p','portal-meta',record.category.toUpperCase()+' · '+(record.visibility==='gm'?'SOMENTE MESTRE':'COMPARTILHADO')),node('p','',record.content));
  card.append(b('Editar registro',()=>recordForm(panel,root,record)));return card;
 }
 function showGM(panel,root){
  panel.append(title('Observatório do Mestre','Um arquivo privado para acompanhar a campanha, a lore, o sistema e suas revisões.'));
  const notice=node('div','portal-gm-banner');notice.append(node('strong','','Acesso de mestre. '),document.createTextNode('As fichas, os registros privados e a auditoria ficam restritos ao usuário autorizado por esta campanha.'));panel.append(notice);
  const tabs=node('div','portal-flex');const labels=[['records','Lore & sistema'],['members','Integrantes'],['audit','Auditoria']];let section=node('div');
  const show=kind=>{section.replaceChildren();for(const btn of tabs.children){btn.classList.toggle('is-active',btn.dataset.kind===kind)}
   if(kind==='records'){
    section.append(node('p','portal-overline','CADERNO DO MESTRE'));
    section.append(b('Criar registro',()=>recordForm(panel,root,null),'portal-action'));
    const list=node('div','portal-list');list.style.marginTop='18px';if(!state.data.records.length)list.append(empty('Nenhum registro criado. Comece pelas anotações de sessão ou pela auditoria das regras.'));
    for(const rec of state.data.records)list.append(gmItem(rec,panel,root));section.append(list);
   }else if(kind==='members'){
    section.append(node('h3','','Integrantes da campanha'));
    const list=node('div','portal-list');for(const m of state.data.members){const card=node('div','portal-item');card.append(node('h3','',state.data.names[m.user_id]||'Integrante'),node('p','portal-meta',(m.role==='gm'?'MESTRE':'JOGADOR')+' · entrou em '+formatTime(m.joined_at)));
     const granted=state.data.mesaGrants.some(g=>g.user_id===m.user_id);
     card.append(node('p','portal-meta',m.user_id===state.user.id?'Mesa liberada automaticamente ao administrador':granted?'MESA DE JOGO · LIBERADA':'MESA DE JOGO · BLOQUEADA'));
     list.append(card)}section.append(list);
    if(state.admin)section.append(brief('Somente o mestre administrador pode liberar ou revogar a Mesa. O sistema verifica a autorização no servidor a cada acesso.'));
    const accessLink=node('a','portal-action','Administrar acessos');accessLink.href='administracao.html';section.append(accessLink);
   }else{
    section.append(node('p','portal-overline','HISTÓRICO IMUTÁVEL'));
    const list=node('div','portal-list');if(!state.data.audit.length)list.append(empty('Nenhuma alteração registrada por enquanto.'));
    for(const entry of state.data.audit){const card=node('div','portal-item');card.append(node('p','',entry.entity_type+' · '+entry.action),node('p','portal-meta',formatTime(entry.occurred_at)+' · '+(state.data.names[entry.actor_id]||'Sistema')));list.append(card)}section.append(list);
   }
  };
  for(const[k,label]of labels){const btn=b(label,()=>show(k));btn.dataset.kind=k;tabs.append(btn)}panel.append(tabs,section);show('records');
 }
 function recordForm(panel,root,existing){if(!isGM())return;
  panel.replaceChildren(title(existing?'Editar registro':'Novo registro do mestre','Registre decisões, pendências e hipóteses sem confundi-las com as regras aprovadas.',b('Voltar',()=>void renderDashboard(root))));
  const form=node('form','portal-form'),name=field('Título','text',existing?.title||'',160),category=selectField('Área',[['lore','Lore'],['sistema','Sistema'],['sessao','Sessão'],['planejamento','Planejamento']],existing?.category),status=selectField('Estado',[['rascunho','Rascunho'],['proposta','Proposta'],['aprovado','Aprovado'],['arquivado','Arquivado']],existing?.status),visibility=selectField('Visibilidade',[['gm','Apenas mestre'],['players','Compartilhar com jogadores']],existing?.visibility),content=field('Notas / decisão / justificativa','textarea',existing?.content||'',30000);name.input.required=true;
  form.append(name.wrap,category.wrap,status.wrap,visibility.wrap,content.wrap);const save=b('Salvar e registrar alteração',()=>{},'portal-action');save.type='submit';form.append(save);
  form.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;const data={title:name.input.value.trim(),category:category.input.value,status:status.input.value,visibility:visibility.input.value,content:content.input.value,updated_at:new Date().toISOString()};
   const op=existing?state.client.from('haema_gm_records').update(data).eq('id',existing.id):state.client.from('haema_gm_records').insert({...data,campaign_id:campaignId(),author_id:state.user.id});
   const r=await notify(op,form,'Registro salvo e auditado.');save.disabled=false;if(r)await renderDashboard(root);
  });panel.append(form);
 }
 async function reload(root){await fetchCampaigns();state.tab='home';if(state.current)await renderDashboard(root);else noCampaign(root)}
 async function init(){
  const root=currentRoot();if(!root)return;const epoch=++state.epoch;root.replaceChildren(node('div','portal-loading','Preparando o seu acesso...'));
  try{
   const client=await ensureClient();if(epoch!==state.epoch||root!==currentRoot())return;if(!client){setup(root);return;}
   // No active session is a normal first visit, not an authentication error.
   const {data:sessionData,error:sessionError}=await client.auth.getSession();
   if(sessionError)throw sessionError;
   if(!sessionData?.session){state.user=null;signin(root);return;}
   const {data,error}=await client.auth.getUser();if(error)throw error;
   state.user=data.user;if(!state.user){signin(root);return}
   const permission=await sharedAccess();
   if(!permission.areas.includes('portal')){accessGate(root,permission,'Portal do jogador');return;}
   state.materials=permission.areas.includes('materials');
   await profile();if(epoch!==state.epoch||root!==currentRoot())return;
   state.admin=!!(await query(client.rpc('haema_is_admin')));
   await reload(root);
  }catch(e){if(epoch!==state.epoch)return;root.replaceChildren();const box=node('div','portal-setup');box.append(node('h2','','Portal temporariamente indisponível'),node('p','',errorText(e)),b('Tentar novamente',()=>void init(),'portal-action'));root.append(box)}
 }
 document.addEventListener('haema:navigated',()=>{
  if(currentRoot())void init();else {state.epoch++;if(state.live&&state.client){void state.client.removeChannel(state.live);state.live=null}}
 });
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>void init(),{once:true});else void init();
 return Object.freeze({init});
})();
